#
# Generate symbolic rule kernel + test inputs + golden predictions.
#
# Phase 4b — emits a self-contained data.h that contains:
#   1. The auto-generated `symbolic_predict()` function (from rule_to_c)
#   2. Pre-scaled int32 test inputs (matching the fixed-point scale)
#   3. Golden predictions from the Python rule reference
#
# The teacher is a small linear classifier with sparse weights so the
# distilled depth-3 decision tree achieves high fidelity. Saliency is the
# mean absolute weight per feature, exactly as Grad-CAM/SHAP would deliver
# on real data.

import argparse
import os
import pathlib
import sys

import hjson
import numpy as np

# Reach the project root so we can import src.xai.symbolic.*
HERE = pathlib.Path(__file__).resolve().parent
PROJECT_ROOT = HERE.parents[4]
sys.path.insert(0, str(PROJECT_ROOT))

# And the SNAX sim utils, for emit_license / format_*.
sys.path.append(str(PROJECT_ROOT / "snax_cluster" / "util" / "sim"))

from data_utils import (  # noqa: E402
    emit_license,
    format_ifdef_wrapper,
    format_scalar_definition,
    format_vector_definition,
)

from src.xai.symbolic.rule_extractor import (  # noqa: E402
    extract_rules,
)
from src.xai.symbolic.rule_to_c import export_to_c_inline  # noqa: E402

BURST_ALIGNMENT = 4096


def make_teacher(n_features: int, n_classes: int, rng: np.random.Generator):
    """Build a sparse linear teacher: class = argmax(W @ x + b).

    Returns:
        (predict_fn, saliency, W, b)
    """
    # Sparse weight matrix: each class only attends to ~3 features.
    W = np.zeros((n_classes, n_features), dtype=np.float32)
    salient_pool = list(range(n_features))
    for c in range(n_classes):
        chosen = rng.choice(salient_pool, size=3, replace=False)
        W[c, chosen] = rng.uniform(0.5, 1.5, size=3).astype(np.float32)
    b = rng.standard_normal(n_classes).astype(np.float32) * 0.1

    def predict(X: np.ndarray) -> np.ndarray:
        logits = X @ W.T + b
        return np.argmax(logits, axis=1).astype(np.int32)

    # Saliency as mean |W| per feature — what averaging Grad-CAM/SHAP gives.
    saliency = np.mean(np.abs(W), axis=0)
    return predict, saliency, W, b


def generate_data(n_features: int, n_classes: int, n_train: int,
                  n_test: int, max_depth: int, top_k: int,
                  scale: int, seed: int):
    """Train teacher, distill rules, build C kernel + golden test set."""
    rng = np.random.default_rng(seed)

    # Training pool — uniform on [0, 1] (matches fixed-point [0, scale])
    X_train = rng.uniform(0.0, 1.0, size=(n_train, n_features)).astype(np.float32)

    teacher, saliency, _, _ = make_teacher(n_features, n_classes, rng)

    rules = extract_rules(
        X=X_train,
        saliency=saliency,
        model_predict=teacher,
        max_depth=max_depth,
        top_k_features=top_k,
    )

    # Test inputs that the SNAX kernel will run.
    X_test = rng.uniform(0.0, 1.0, size=(n_test, n_features)).astype(np.float32)
    py_preds = rules.predict_batch(X_test).astype(np.int32)

    # Pre-scale test inputs to fixed-point int32, matching the C kernel.
    X_test_int = np.round(X_test * scale).astype(np.int32)

    # Generate the C function from the rules.
    c_kernel = export_to_c_inline(
        rules,
        function_name="symbolic_predict",
        input_name="x",
        scale=scale,
    )

    return rules, c_kernel, X_test_int, py_preds, saliency


def emit_header(**kwargs) -> str:
    n_features = kwargs["n_features"]
    n_classes = kwargs["n_classes"]
    n_test = kwargs["n_test_inputs"]
    max_depth = kwargs["max_depth"]
    top_k = kwargs["top_k_features"]
    n_train = kwargs["n_train_samples"]
    scale = kwargs["fixed_point_scale"]
    seed = kwargs["seed"]
    section = kwargs.get("section")

    rules, c_kernel, X_test_int, py_preds, saliency = generate_data(
        n_features=n_features,
        n_classes=n_classes,
        n_train=n_train,
        n_test=n_test,
        max_depth=max_depth,
        top_k=top_k,
        scale=scale,
        seed=seed,
    )

    blocks = [emit_license()]
    blocks += [
        f"// Auto-generated by datagen.py — do not edit.",
        f"// Teacher: sparse linear classifier ({n_features} features, "
        f"{n_classes} classes)",
        f"// Distilled tree: {rules.n_nodes} nodes, {rules.n_leaves} leaves, "
        f"depth ≤ {rules.max_depth}",
        f"// Train fidelity: {rules.train_fidelity:.4f}",
        f"// Fixed-point scale: {scale}",
    ]
    blocks += [
        format_scalar_definition("uint32_t", "N_FEATURES", n_features),
        format_scalar_definition("uint32_t", "N_CLASSES", n_classes),
        format_scalar_definition("uint32_t", "N_TEST_INPUTS", n_test),
        format_scalar_definition("uint32_t", "FP_SCALE", scale),
    ]

    # Test inputs flattened in row-major order: test_inputs[i*N_FEATURES + j]
    blocks += [
        format_vector_definition(
            "int32_t",
            "test_inputs",
            X_test_int.flatten(),
            alignment=BURST_ALIGNMENT,
            section=section,
        )
    ]

    # Output buffer for the kernel to write predictions into.
    blocks += [
        format_vector_definition(
            "int32_t",
            "test_outputs",
            np.zeros(n_test, dtype=np.int32),
            alignment=BURST_ALIGNMENT,
            section=section,
        )
    ]

    # Golden predictions under BIST guard.
    golden_def = format_vector_definition(
        "int32_t", "golden_predictions", py_preds
    )
    blocks += [format_ifdef_wrapper("BIST", golden_def)]

    # Finally, the auto-generated rule function as static inline.
    blocks += [c_kernel]

    return "\n\n".join(blocks)


def main():
    parser = argparse.ArgumentParser(
        description="Generate symbolic rule kernel + test data"
    )
    parser.add_argument(
        "-c", "--cfg", type=pathlib.Path, required=True,
        help="Param config file (hjson)",
    )
    parser.add_argument(
        "--section", type=str, default=None,
        help="Section to store arrays in",
    )
    args = parser.parse_args()

    with args.cfg.open() as f:
        param = hjson.loads(f.read())
    param["section"] = args.section

    print(emit_header(**param))


if __name__ == "__main__":
    main()
